/**
 * תנועה לעמודים פנימיים — אותה מערכת כמו בדף הבית (REDESIGN-PLAN §6), בלי הבמה:
 * חשיפות מדורגות, כותרות מילה-מילה, מגנטיות/הטיה (עכבר), קרוסלות, פרלקסה בכותרת ויריעות שמגיעות מעומק.
 */
import { gsap, ScrollTrigger, reduced, finePointer, fwd, isRTL } from './core';
import { initSplit, playSplit } from './split';
import { initMagnetic, initTilt } from './pointer';
import { initReveal } from '../lib/reveal';
import { initCarousels } from '../lib/carousel';

export function initInnerPage() {
  initReveal();
  initSplit();
  initCarousels();
  initMagnetic();
  initTilt();
  // הכותרת הראשית: אין וילון פתיחה בעמודים פנימיים — נחשפת מיד
  document.querySelectorAll('[data-split="now"]').forEach((el) => playSplit(el));
  if (reduced()) return;
  // פרלקסה: התמונה בכותרת זזה לאט מהתוכן (עומק), בלי תלות במהירות הגלילה
  gsap.utils.toArray<HTMLElement>('[data-parallax]').forEach((img) => {
    gsap.fromTo(img, { yPercent: -4 }, { yPercent: 10, ease: 'none', scrollTrigger: { trigger: img.parentElement!, start: 'top top', end: 'bottom top', scrub: true } });
  });
  // יריעות מעומק (דסקטופ בלבד — במובייל יריעה גבוהה לא "מגיעה" בזמן שקוראים אותה)
  if (!matchMedia('(min-width: 1000px)').matches) return;
  gsap.utils.toArray<HTMLElement>('[data-depth]').forEach((el) => {
    const side = el.dataset.depth === 'side';
    gsap.set(el, { transformPerspective: 1400, transformOrigin: side ? (isRTL() ? '100% 50%' : '0% 50%') : '50% 100%' });
    gsap.fromTo(el, side ? { rotationY: -12 * fwd(), x: 70 * -fwd(), opacity: 0 } : { rotationX: 12, y: 110, opacity: 0 },
      { rotationX: 0, rotationY: 0, x: 0, y: 0, opacity: 1, ease: 'power2.out', scrollTrigger: { trigger: el, start: 'top bottom', end: 'top 72%', scrub: finePointer() ? 0.5 : true } });
  });
  ScrollTrigger.refresh();
}
